/* Nội dung tự biên soạn. Mỗi bài: tiêu đề, khái niệm, các điểm chính,
   lệnh minh họa, bài tập, tiêu chí kiểm tra, lỗi thường gặp, đường dẫn tài liệu. */
const CHAPTERS = [
{title:'Giới thiệu khóa học',en:'Introduction',intro:'Bắt đầu hành trình quản trị Kubernetes. Hiểu cách sử dụng sổ tay, chuẩn bị môi trường thực hành và hình thành thói quen kiểm chứng sau mỗi thao tác.',goals:['Nắm lộ trình từ kiến trúc đến vận hành cluster.','Chuẩn bị terminal, kubectl và một cluster học tập.','Kết hợp đọc ngắn, thực hành và tự kiểm tra.'],lessons:[
['Chào mừng đến với Kubernetes CKA','Kubernetes điều phối ứng dụng container bằng cách liên tục đưa trạng thái thực tế về trạng thái bạn khai báo. Sổ tay này tập trung vào tư duy và thao tác của người quản trị cluster.', ['Đọc phần mở đầu trước khi học các bài trong phần.','Mỗi bài gồm khái niệm, lệnh minh họa, bài tập và cách kiểm tra.','Các bài là ghi chú độc lập theo chủ đề CKA; số bài không tương ứng số lecture Udemy.'], 'kubectl version --client\nkubectl cluster-info\nkubectl get nodes', 'Xác định phiên bản kubectl, cluster đang kết nối và danh sách node. Ghi lại kết quả vào nhật ký học tập.', 'Giải thích được client, API server và node khác nhau ở đâu.', 'Không chạy lệnh sửa tài nguyên trên cluster công việc khi đang luyện tập.', '/docs/concepts/overview/'],
['Lộ trình học và cách thực hành','Học quản trị cluster cần cả hiểu cơ chế và phản xạ sử dụng công cụ. Một vòng học hiệu quả là dự đoán kết quả, chạy lệnh, quan sát rồi giải thích sự khác biệt.', ['Đi từ Pod, Deployment và Service tới scheduling, cấu hình và bảo mật.','Tiếp tục với mạng, lưu trữ, bảo trì và xử lý sự cố.','Sau mỗi phần, tự làm lại bài tập mà không nhìn lệnh mẫu.'], 'kubectl api-resources\nkubectl explain pod\nkubectl explain deployment.spec', 'Dùng kubectl explain để tìm trường replicas của Deployment và trường containers của Pod.', 'Tìm được cấu trúc tài nguyên từ tài liệu tích hợp thay vì chỉ học thuộc YAML.', 'Thông tin kỳ thi có thể thay đổi; kiểm tra nguồn chứng nhận chính thức khi đăng ký.', '/docs/reference/kubectl/'],
['Chuẩn bị môi trường học tập','Một cluster học tập tách biệt giúp bạn thử nghiệm lỗi và khôi phục an toàn. Có thể dùng lab của khóa học hoặc cluster cục bộ với kind/minikube; bài bảo trì node cần môi trường có quyền quản trị phù hợp.', ['Cần kiến thức Linux cơ bản, YAML và container.','Kiểm tra context trước mọi bài lab.','Dùng namespace riêng để dễ quản lý tài nguyên thực hành.'], 'kubectl config current-context\nkubectl create namespace cka-lab\nkubectl get pods -n cka-lab', 'Tạo namespace cka-lab. Trong các bài tiếp theo, thêm -n cka-lab với tài nguyên có namespace.', 'Namespace tồn tại và không có tài nguyên ngoài ý muốn.', 'Namespace không cô lập node, PersistentVolume hay ClusterRole.', '/docs/tasks/tools/'],
['kubectl: context, namespace và trợ giúp','kubectl gửi yêu cầu tới API server theo kubeconfig. Context kết hợp cluster, thông tin xác thực và namespace mặc định; chọn nhầm context là một lỗi vận hành nghiêm trọng.', ['current-context cho biết đích kết nối hiện tại.','Dùng -n để chỉ định namespace rõ ràng trong lệnh thực hành.','--help và explain giúp tìm cờ lệnh và schema API.'], 'kubectl config get-contexts\nkubectl config current-context\nkubectl get pods -n cka-lab\nkubectl get --help', 'Đọc danh sách context và tìm namespace mặc định của context hiện tại, không thay đổi context khi chưa xác định đúng cluster lab.', 'Nêu được cluster và namespace mà một lệnh sẽ tác động.', 'Lệnh dùng -A đọc toàn bộ namespace; không có nghĩa tài nguyên là cluster-scoped.', '/docs/concepts/configuration/organize-cluster-access-kubeconfig/']
]},
{title:'Kiến trúc & khái niệm cốt lõi',en:'Core Concepts',intro:'Khám phá bộ máy phía sau Kubernetes: control plane, worker node và các đối tượng API. Từ một Pod đơn lẻ, bạn sẽ xây dựng ứng dụng có nhiều bản sao và địa chỉ truy cập ổn định.',goals:['Phân biệt vai trò các thành phần cluster.','Tạo và đọc YAML của Pod, ReplicaSet, Deployment.','Kết nối ứng dụng qua Service và namespace.'],lessons:[
['Kiến trúc Kubernetes Cluster','Control plane quản lý trạng thái mong muốn; worker node chạy workload. Các thành phần trao đổi chủ yếu qua Kubernetes API, tạo nên một hệ thống điều khiển phân tán.', ['API server cung cấp API; etcd lưu dữ liệu trạng thái cluster.','Scheduler chọn node cho Pod chưa được gán node.','Controller liên tục đối chiếu trạng thái; kubelet quản lý Pod trên node.'], 'kubectl get nodes -o wide\nkubectl get pods -n kube-system\nkubectl cluster-info', 'Lập sơ đồ đường đi từ kubectl đến API server, rồi tới scheduler và kubelet khi tạo Pod.', 'Phân biệt thành phần chọn node với thành phần chạy container.', 'Control plane không trực tiếp chạy mọi container ứng dụng.', '/docs/concepts/overview/components/'],
['Container runtime: containerd và CRI','Kubelet dùng Container Runtime Interface để yêu cầu runtime tạo container. containerd và CRI-O là các runtime hỗ trợ CRI; một image Docker đúng chuẩn OCI vẫn có thể chạy trong cluster.', ['CRI là giao diện giữa kubelet và runtime.','Runtime tải image và quản lý vòng đời container.','crictl hỗ trợ quan sát runtime ở mức node khi được cấu hình đúng endpoint.'], 'kubectl get nodes -o custom-columns=NAME:.metadata.name,RUNTIME:.status.nodeInfo.containerRuntimeVersion\n# Trên node lab có crictl đã cấu hình:\nsudo crictl ps', 'Xác định runtime của từng node bằng kubectl; chỉ kiểm tra crictl khi có quyền truy cập node lab.', 'Đọc được tên và phiên bản runtime trong trạng thái Node.', 'Docker CLI và crictl không cùng một giao diện quản lý.', '/docs/setup/production-environment/container-runtimes/'],
['Pod và vòng đời của Pod','Pod là đơn vị triển khai nhỏ nhất của Kubernetes, chứa một hoặc nhiều container dùng chung network namespace và có thể dùng chung volume. Pod là tài nguyên có vòng đời hữu hạn.', ['Các container trong Pod giao tiếp qua localhost.','Pod có phase như Pending, Running, Succeeded, Failed; trạng thái container cung cấp chi tiết hơn.','Pod được thay thế có UID và có thể có IP mới.'], 'kubectl run web --image=nginx:stable -n cka-lab\nkubectl get pod web -n cka-lab -o wide\nkubectl describe pod web -n cka-lab', 'Tạo Pod web, đọc image, node, IP và Events. Chưa có cluster thì đọc YAML sinh bởi --dry-run=client -o yaml.', 'Pod Running và container Ready; giải thích được các Events khởi tạo.', 'Running không đồng nghĩa ứng dụng sẵn sàng nhận request.', '/docs/concepts/workloads/pods/pod-lifecycle/'],
['YAML và quản lý tài nguyên khai báo','Manifest diễn tả trạng thái mong muốn bằng apiVersion, kind, metadata và spec. kubectl apply gửi thay đổi để controller điều chỉnh trạng thái thực tế.', ['metadata.name định danh tài nguyên trong phạm vi của nó.','spec là yêu cầu; status do hệ thống cập nhật.','Dùng dry-run để tạo hoặc kiểm tra manifest trước khi áp dụng.'], 'kubectl run demo --image=nginx:stable -n cka-lab --dry-run=client -o yaml > pod.yaml\nkubectl apply -f pod.yaml\nkubectl get pod demo -n cka-lab -o yaml', 'Sinh pod.yaml, thêm label app: demo trong metadata.labels rồi apply.', 'Label xuất hiện trong kết quả kubectl get pod --show-labels.', 'YAML nhạy với thụt lề; nhiều trường của Pod không thể sửa trực tiếp sau khi tạo.', '/docs/concepts/overview/working-with-objects/'],
['ReplicaSet và Deployment','ReplicaSet giữ số lượng Pod theo selector; Deployment quản lý ReplicaSet và việc cập nhật phiên bản. Thông thường hãy tạo Deployment cho ứng dụng stateless thay vì quản lý ReplicaSet trực tiếp.', ['Deployment tạo ReplicaSet, ReplicaSet tạo Pod.','replicas là số bản sao mong muốn.','Selector cần khớp labels trong Pod template.'], 'kubectl create deployment app --image=nginx:stable --replicas=3 -n cka-lab\nkubectl get deploy,rs,pods -n cka-lab\nkubectl scale deployment app --replicas=2 -n cka-lab', 'Tạo Deployment app, giảm còn hai replica và quan sát controller điều chỉnh.', 'Deployment có 2/2 replica sẵn sàng; nhận diện ownerReferences của Pod.', 'Sửa một Pod do Deployment quản lý không cập nhật template cho các Pod tương lai.', '/docs/concepts/workloads/controllers/deployment/'],
['Service và namespace','Service cung cấp điểm truy cập ổn định tới một nhóm endpoint, thường được xác định bằng label selector. Namespace chia tài nguyên thành các phạm vi tên trong cùng cluster.', ['ClusterIP dùng cho truy cập nội bộ.','NodePort mở cổng trên node; LoadBalancer cần hạ tầng hỗ trợ.','Service port là cổng khách gọi; targetPort là cổng ứng dụng đích.'], 'kubectl expose deployment app --port=80 --target-port=80 -n cka-lab\nkubectl get service app -n cka-lab\nkubectl get endpointslices -n cka-lab -l kubernetes.io/service-name=app', 'Expose Deployment app từ bài trước và kiểm tra địa chỉ backend trong EndpointSlice.', 'Selector Service khớp labels Pod và có endpoint Ready.', 'Service không có endpoint thường do selector sai hoặc Pod chưa Ready.', '/docs/concepts/services-networking/service/']
]},
{title:'Lập lịch workload',en:'Scheduling',intro:'Tìm hiểu vì sao một Pod được đặt lên một node cụ thể. Thực hành labels, taints, affinity và tài nguyên để điều khiển scheduling có chủ đích.',goals:['Đọc Events khi Pod Pending.','Phân biệt lọc node với cho phép chịu taint.','Thiết lập requests và limits hợp lý.'],lessons:[
['Labels, selectors và annotations','Labels là cặp khóa–giá trị dùng để nhóm và chọn tài nguyên. Annotations lưu metadata bổ sung, không được dùng như label selector.', ['Selector kết nối Deployment, Service và Pod.','Dùng quy ước label nhất quán theo ứng dụng, tầng và môi trường.','Có thể lọc theo phép bằng hoặc tập giá trị.'], 'kubectl label pod demo tier=frontend -n cka-lab --overwrite\nkubectl get pods -n cka-lab -l tier=frontend\nkubectl get pods -n cka-lab --show-labels', 'Gắn tier=frontend cho Pod demo rồi tìm lại chỉ bằng selector.', 'Kết quả chỉ chứa Pod khớp label đã đặt.', 'Đổi label có thể làm Service mất backend hoặc ảnh hưởng controller.', '/docs/concepts/overview/working-with-objects/labels/'],
['Taints và tolerations','Taint trên node đẩy lùi các Pod không có toleration tương ứng. Toleration chỉ cho phép Pod được cân nhắc lên node đó, không ép scheduler chọn node đó.', ['NoSchedule ngăn Pod mới không phù hợp.','PreferNoSchedule là ưu tiên mềm.','NoExecute có thể đuổi Pod đang chạy nếu không có toleration phù hợp.'], '# Chỉ chạy trên node lab được chọn\nkubectl taint nodes <node-lab> dedicated=training:NoSchedule\nkubectl describe node <node-lab>\n# Gỡ taint sau bài lab\nkubectl taint nodes <node-lab> dedicated=training:NoSchedule-', 'Thêm taint trên node lab; tạo Pod có và không có toleration để so sánh Events. Gỡ taint sau bài.', 'Giải thích được vì sao Pod bị từ chối và vì sao toleration không đảm bảo placement.', 'Không thử NoExecute trên node đang chạy workload cần giữ.', '/docs/concepts/scheduling-eviction/taint-and-toleration/'],
['Node selector và node affinity','nodeSelector yêu cầu node có labels khớp. Node affinity diễn tả điều kiện phong phú hơn, bao gồm bắt buộc và ưu tiên, để scheduler chọn nơi chạy workload.', ['requiredDuringSchedulingIgnoredDuringExecution là điều kiện bắt buộc lúc scheduling.','preferredDuringSchedulingIgnoredDuringExecution chỉ tăng điểm ưu tiên.','IgnoredDuringExecution không tự đuổi Pod khi label node đổi sau khi scheduling.'], 'kubectl get nodes --show-labels\nkubectl explain pod.spec.nodeSelector\nkubectl explain pod.spec.affinity.nodeAffinity', 'Viết manifest Pod có nodeSelector khớp label của node lab; thay bằng label không tồn tại và đọc Events.', 'Phân biệt lỗi không có node khớp với lỗi thiếu tài nguyên.', 'Đặt spec.nodeName bỏ qua scheduler; tránh dùng để thay affinity trong vận hành thông thường.', '/docs/concepts/scheduling-eviction/assign-pod-node/'],
['Requests, limits và LimitRange','Scheduler sử dụng requests để xét khả năng đặt Pod. CPU limit được thực thi bằng throttling; vượt giới hạn bộ nhớ có thể dẫn tới OOM kill.', ['CPU 100m là một phần mười CPU.','Requests và limits là hai mục đích khác nhau.','LimitRange có thể đặt giá trị mặc định; ResourceQuota giới hạn tổng tài nguyên trong namespace.'], 'kubectl set resources deployment app -n cka-lab --requests=cpu=100m,memory=64Mi --limits=cpu=500m,memory=256Mi\nkubectl describe deployment app -n cka-lab\nkubectl get resourcequota,limitrange -n cka-lab', 'Đặt requests/limits cho Deployment app, quan sát rollout và trạng thái Pod mới.', 'Pod template có đủ CPU/memory requests và limits.', 'Scheduler không dựa đơn thuần vào CPU sử dụng tức thời để đặt Pod.', '/docs/concepts/configuration/manage-resources-containers/'],
['DaemonSet, static Pod và priority','DaemonSet duy trì Pod trên mỗi node phù hợp, thường cho agent hệ thống. Static Pod do kubelet đọc từ manifest cục bộ; mirror Pod trên API phản ánh Pod đó.', ['DaemonSet không dùng replicas như Deployment.','Static Pod được quản lý từ node chứa manifest.','PriorityClass ảnh hưởng thứ tự ưu tiên và có thể liên quan preemption.'], 'kubectl get daemonsets -A\nkubectl get pods -n kube-system -o wide\nkubectl get priorityclasses\nkubectl explain daemonset.spec', 'Tìm một DaemonSet trong cluster và so sánh desired/current/ready với số node đủ điều kiện.', 'Nêu được vì sao agent mạng thường dùng DaemonSet.', 'Xóa mirror Pod qua API không loại bỏ manifest static Pod trên node.', '/docs/concepts/workloads/controllers/daemonset/']
]},
{title:'Logging & giám sát',en:'Logging & Monitoring',intro:'Quan sát cluster trước khi sửa lỗi. Kết hợp logs, Events và metrics để phân biệt triệu chứng ứng dụng với vấn đề tài nguyên hoặc hạ tầng.',goals:['Thu thập logs của container đúng thời điểm.','Đọc Events và metrics có ngữ cảnh.','Phân biệt Startup, Readiness và Liveness probe.'],lessons:[
['Logs của Pod và container','kubectl logs đọc stdout/stderr của container qua kubelet. Với Pod nhiều container, chỉ định -c; nếu container đã restart, --previous giúp xem log lần chạy trước.', ['--tail giới hạn số dòng; --since giới hạn khoảng thời gian.','-f theo dõi dòng log mới.','Log cũ có thể mất khi bị xoay hoặc Pod bị xóa; hệ thống tập trung cần collector riêng.'], 'kubectl logs deployment/app -n cka-lab --tail=50\nkubectl logs <pod> -n cka-lab -c <container> --previous\nkubectl logs <pod> -n cka-lab --since=10m', 'Đọc log của ứng dụng lab, ghi lại timestamp và thông báo đầu tiên liên quan lỗi.', 'Chọn đúng Pod, container và lần chạy phát sinh sự cố.', 'CrashLoopBackOff là trạng thái backoff; nguyên nhân cần tìm trong logs, exit code và Events.', '/docs/concepts/cluster-administration/logging/'],
['Events và quy trình quan sát','Events ghi nhận các sự kiện như scheduling thất bại, pull image, probe lỗi hoặc volume mount lỗi. Chúng là manh mối ngắn hạn, cần đọc cùng trạng thái tài nguyên.', ['Bắt đầu bằng get để nhìn tổng quan.','Dùng describe để liên hệ conditions, container state và Events.','Sắp xếp Events theo thời điểm để dựng lại diễn biến.'], 'kubectl get pods -n cka-lab -o wide\nkubectl describe pod <pod> -n cka-lab\nkubectl get events -n cka-lab --sort-by=.metadata.creationTimestamp', 'Tạo một Pod dùng image không tồn tại trong lab; đọc Events rồi sửa manifest hoặc xóa Pod thử nghiệm.', 'Phân biệt ImagePullBackOff với Pending do scheduler.', 'Events được giữ trong thời gian hữu hạn, không phải nhật ký audit lâu dài.', '/docs/tasks/debug/debug-application/debug-pods/'],
['Metrics Server và kubectl top','kubectl top sử dụng Metrics API để hiển thị CPU và bộ nhớ gần đây. Cluster cần thành phần cung cấp metrics phù hợp, thường là Metrics Server.', ['top giúp kiểm tra mức sử dụng, không thay hệ thống monitoring lịch sử.','Requests dùng cho scheduling khác với usage thực tế.','Nếu API metrics không có, kiểm tra addon và kết nối kubelet.'], 'kubectl top nodes\nkubectl top pods -n cka-lab --containers\nkubectl get apiservice v1beta1.metrics.k8s.io', 'Nếu cluster có metrics, so sánh usage của app với requests đã đặt. Nếu chưa có, ghi rõ điều kiện thiếu.', 'Đọc đúng đơn vị CPU và memory; nhận biết API metrics chưa sẵn sàng.', 'Không bỏ qua kiểm tra TLS để chữa lỗi metrics một cách tùy tiện.', '/docs/tasks/debug/debug-cluster/resource-metrics-pipeline/'],
['Startup, readiness và liveness probes','Startup probe cho ứng dụng thời gian khởi động. Readiness quyết định Pod có nên nhận traffic; liveness phát hiện container cần được khởi động lại.', ['Startup thành công rồi các probe khác mới bắt đầu khi có cấu hình startup probe.','Readiness thất bại loại Pod khỏi endpoint sẵn sàng.','Liveness thất bại đủ ngưỡng có thể kích hoạt restart container.'], 'kubectl explain pod.spec.containers.readinessProbe\nkubectl explain pod.spec.containers.livenessProbe\nkubectl describe pod <pod> -n cka-lab', 'Thêm HTTP readiness probe đường dẫn / cổng 80 vào template Deployment app rồi quan sát Ready.', 'Khi cố ý đặt đường dẫn readiness sai, Pod có thể Running nhưng không Ready.', 'Dùng cùng một phép kiểm tra phụ thuộc bên ngoài cho liveness có thể gây restart hàng loạt.', '/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/']
]},
{title:'Vòng đời ứng dụng',en:'Application Lifecycle Management',intro:'Quản lý cấu hình và triển khai phiên bản mới có kiểm soát. Hiểu điều gì xảy ra khi đổi image, đưa cấu hình vào container hoặc chạy tác vụ định kỳ.',goals:['Theo dõi rollout và thực hiện rollback trong lab.','Dùng ConfigMap, Secret và init container.','Phân biệt workload dài hạn với Job/CronJob.'],lessons:[
['Rolling update và rollback','Deployment tạo ReplicaSet mới khi Pod template thay đổi. RollingUpdate thay dần Pod theo maxSurge và maxUnavailable; rollback sử dụng revision trước nếu lịch sử còn được giữ.', ['rollout status theo dõi tiến độ.','rollout history liệt kê revision.','Rollback template không khôi phục dữ liệu bên ngoài hoặc nội dung Secret đã thay đổi.'], 'kubectl set image deployment/app nginx=nginx:1.28 -n cka-lab\nkubectl rollout status deployment/app -n cka-lab\nkubectl rollout history deployment/app -n cka-lab\n# Chỉ rollback khi cần trong lab:\nkubectl rollout undo deployment/app -n cka-lab', 'Kiểm tra tên container trước khi set image; cập nhật một phiên bản nginx phù hợp rồi xem ReplicaSet mới.', 'Rollout hoàn tất hoặc xác định được lý do chưa hoàn tất từ Events.', 'Tên container trong lệnh set image phải khớp template, không nhất thiết là tên Deployment.', '/docs/concepts/workloads/controllers/deployment/'],
['Commands, arguments và biến môi trường','command và args trong Pod có thể ghi đè entrypoint/cmd mặc định của image. Biến môi trường truyền cấu hình khi container khởi tạo.', ['command tương ứng phần executable được thay thế.','args cung cấp đối số cho command.','Thay Pod template để cập nhật cấu hình bền vững qua controller.'], 'kubectl run greeting --image=busybox:1.37 -n cka-lab --restart=Never -- /bin/sh -c "echo Hello Kubernetes"\nkubectl logs greeting -n cka-lab\nkubectl get pod greeting -n cka-lab', 'Chạy Pod in lời chào và quan sát phase Succeeded sau khi tiến trình thoát.', 'Giải thích được vì sao container kết thúc bình thường và không chạy mãi.', 'Shell expansion cần shell thực thi; Kubernetes không tự chèn shell cho mọi command.', '/docs/tasks/inject-data-application/define-command-argument-container/'],
['ConfigMap và Secret','ConfigMap chứa cấu hình không nhạy cảm; Secret được thiết kế cho dữ liệu nhạy cảm. Có thể tham chiếu bằng biến môi trường hoặc volume, mỗi cách có hành vi cập nhật khác nhau.', ['Base64 không phải mã hóa bảo mật.','Giới hạn RBAC và bật bảo vệ dữ liệu lưu trữ khi triển khai thực tế.','Biến môi trường không tự đổi trong tiến trình khi đối tượng nguồn thay đổi.'], 'kubectl create configmap app-config --from-literal=APP_MODE=training -n cka-lab\nkubectl create secret generic demo-secret --from-literal=password=example-only -n cka-lab\nkubectl describe configmap app-config -n cka-lab', 'Mount ConfigMap vào Pod lab bằng volume hoặc dùng envFrom, rồi đọc giá trị từ container.', 'Ứng dụng nhìn thấy giá trị mong đợi ở đúng đường dẫn hoặc biến môi trường.', 'Chỉ dùng giá trị giả trong lab; tránh lưu Secret thật trong Git hoặc lịch sử terminal.', '/docs/concepts/configuration/secret/'],
['Multi-container Pod và init container','Các container trong cùng Pod chia sẻ mạng và có thể chia sẻ volume. Init container thông thường chạy đến khi hoàn tất trước khi app container bắt đầu.', ['Sidecar hỗ trợ ứng dụng bằng chức năng bổ sung.','Init container phù hợp cho chuẩn bị dữ liệu hoặc kiểm tra điều kiện ban đầu.','Nếu init container thất bại, app container có thể chưa được khởi tạo.'], 'kubectl explain pod.spec.initContainers\nkubectl get pod <pod> -n cka-lab -o jsonpath="{.status.initContainerStatuses}"\nkubectl logs <pod> -c <init-container> -n cka-lab', 'Viết Pod có init container tạo một file trong emptyDir; app container đọc file qua cùng volume.', 'File được tạo trước khi app chạy và đọc được qua volume chia sẻ.', 'Một vòng chờ vô hạn trong init container có thể giữ Pod ở trạng thái Init.', '/docs/concepts/workloads/pods/init-containers/'],
['Jobs và CronJobs','Job theo dõi tác vụ chạy đến khi hoàn tất; CronJob tạo Job theo lịch. Tác vụ cần thiết kế để chịu được retry hoặc chạy lặp mà không làm sai dữ liệu.', ['completions và parallelism điều khiển số lần hoàn tất và mức song song.','backoffLimit giới hạn retry theo cơ chế Job.','concurrencyPolicy và timeZone giúp diễn đạt hành vi lịch chạy rõ hơn.'], 'kubectl create job hello --image=busybox:1.37 -n cka-lab -- echo hello\nkubectl wait --for=condition=complete job/hello -n cka-lab --timeout=60s\nkubectl logs job/hello -n cka-lab\nkubectl create cronjob heartbeat --image=busybox:1.37 --schedule="*/5 * * * *" -n cka-lab -- echo tick', 'Tạo Job hello; với CronJob, kiểm tra manifest trước và xóa lịch sau khi học để tránh sinh Job tiếp tục.', 'Job Complete và log chứa kết quả mong đợi.', 'CronJob không bảo đảm chính xác một lần thực thi; thiết kế tác vụ idempotent.', '/docs/concepts/workloads/controllers/cron-jobs/']
]},
{title:'Bảo trì cluster',en:'Cluster Maintenance',intro:'Luyện cách bảo trì node, sao lưu trạng thái và lên kế hoạch nâng cấp. Những thao tác này cần môi trường lab có quyền quản trị node và quy trình phục hồi rõ ràng.',goals:['Phân biệt cordon, drain và uncordon.','Hiểu sao lưu etcd và phục hồi dữ liệu.','Lên thứ tự nâng cấp theo tài liệu đúng phiên bản.'],lessons:[
['Cordon, drain và uncordon','Cordon đánh dấu node không nhận Pod mới từ scheduler. Drain cố gắng di chuyển workload bằng eviction; uncordon cho phép scheduler sử dụng lại node sau bảo trì.', ['Drain cần tính đến PodDisruptionBudget.','DaemonSet không được di chuyển như Pod của Deployment.','emptyDir là dữ liệu tạm; xem xét trước khi chấp nhận mất dữ liệu.'], '# Trên cluster lab nhiều node\nkubectl cordon <node-lab>\nkubectl drain <node-lab> --ignore-daemonsets\nkubectl uncordon <node-lab>', 'Đọc Pod đang chạy trên node và PDB trước khi drain; kiểm tra workload đã được tạo lại ở node khác.', 'Node trở lại Ready,SchedulingEnabled sau uncordon và ứng dụng đủ replica.', 'Không thêm --force hoặc --delete-emptydir-data khi chưa hiểu dữ liệu và Pod bị ảnh hưởng.', '/docs/tasks/administer-cluster/safely-drain-node/'],
['PodDisruptionBudget','PDB giới hạn mức gián đoạn tự nguyện của một nhóm Pod khi thao tác dùng Eviction API. Nó không bảo vệ trước mọi lỗi node và không thay thế chiến lược rollout của Deployment.', ['minAvailable và maxUnavailable diễn đạt ngân sách gián đoạn.','Selector phải khớp Pod cần bảo vệ.','PDB quá chặt có thể chặn drain.'], 'kubectl get pdb -A\nkubectl explain poddisruptionbudget.spec\nkubectl describe pdb <pdb-name> -n cka-lab', 'Tạo PDB minAvailable: 1 cho Deployment app có hai replica trong lab; đọc disruptionsAllowed.', 'Giải thích được vì sao ngân sách thay đổi khi một Pod chưa Ready.', 'PDB không ngăn được mọi kiểu xóa Pod trực tiếp.', '/docs/tasks/run-application/configure-pdb/'],
['Sao lưu và phục hồi etcd','etcd giữ trạng thái API của cluster. Snapshot là một phần quan trọng của kế hoạch phục hồi; thao tác cần endpoint và chứng chỉ đúng với cấu hình thực tế.', ['Xác định topology, đường dẫn chứng chỉ và phiên bản công cụ trước khi sao lưu.','Dùng etcdctl snapshot save; kiểm tra snapshot bằng etcdutl tương thích.','Phục hồi cần quy trình riêng, data directory mới và xử lý membership theo topology.'], '# Ví dụ trên control-plane lab; thay đường dẫn theo cấu hình thực tế\nETCDCTL_API=3 etcdctl --endpoints=https://127.0.0.1:2379 \\\n  --cacert=<ca.crt> --cert=<client.crt> --key=<client.key> \\\n  snapshot save snapshot.db\netcdutl snapshot status snapshot.db -w table', 'Viết checklist backup/restore cho cluster lab; chỉ tạo snapshot khi có quyền, không thử restore trên cluster đang dùng.', 'Snapshot kiểm tra được và có bản ghi phiên bản, thời điểm, topology.', 'Snapshot chứa dữ liệu nhạy cảm; bảo vệ bản sao. Không chạy restore theo lệnh đoán sẵn.', '/docs/tasks/administer-cluster/configure-upgrade-etcd/'],
['Nâng cấp cluster bằng kubeadm','Nâng cấp cần kiểm tra version skew, khả năng tương thích addon và bản sao lưu trước khi làm. Với kubeadm, nâng control plane trước rồi từng worker theo hướng dẫn của phiên bản đích.', ['Chọn tài liệu đúng phiên bản hiện tại và đích; không nhảy qua bước hỗ trợ.','Drain node phù hợp trước khi thay đổi thành phần.','Kiểm tra trạng thái node, system Pods và ứng dụng sau từng bước.'], 'kubectl version\nkubectl get nodes\n# Trên control-plane lab có kubeadm:\nsudo kubeadm upgrade plan\n# Đọc quy trình phiên bản đích trước khi apply', 'Lập kế hoạch nâng cấp một minor version cho cluster lab, ghi rõ rollback/restore và thứ tự các node.', 'Có danh sách kiểm tra trước/sau và phương án nếu node không Ready.', 'Không sao chép lệnh cài package cố định từ một phiên bản Kubernetes khác.', '/docs/tasks/administer-cluster/kubeadm/kubeadm-upgrade/']
]},
{title:'Bảo mật Kubernetes',en:'Security',intro:'Bảo vệ API và workload bằng xác thực, phân quyền tối thiểu và cấu hình thực thi phù hợp. Học cách kiểm tra một quyền trước khi cấp thêm quyền.',goals:['Đọc kubeconfig và hiểu chứng chỉ TLS.','Tạo Role/RoleBinding theo nguyên tắc tối thiểu.','Dùng ServiceAccount và security context đúng mục đích.'],lessons:[
['Xác thực, TLS và kubeconfig','API server cần xác định danh tính người gọi trước khi xét quyền. kubeconfig lưu địa chỉ cluster, CA và tham chiếu thông tin xác thực để kubectl kết nối.', ['TLS xác minh máy chủ và bảo vệ kênh truyền.','Client certificate hoặc token có thể là phương thức xác thực tùy cluster.','Không chia sẻ kubeconfig có credential với người không được cấp quyền.'], 'kubectl config current-context\nkubectl config view --minify\n# Trên cluster kubeadm lab:\nsudo kubeadm certs check-expiration', 'Xác định đường dẫn CA và phương thức xác thực trong context; không xuất nội dung private key.', 'Phân biệt lỗi chứng chỉ, lỗi Unauthorized và lỗi Forbidden.', 'Không dùng --insecure-skip-tls-verify như giải pháp lâu dài cho lỗi TLS.', '/docs/concepts/security/controlling-access/'],
['RBAC: Role và RoleBinding','RBAC cấp quyền bằng các verbs trên tài nguyên API. Role giới hạn trong namespace; ClusterRole có thể mô tả quyền ở cấp cluster hoặc được tham chiếu qua binding phù hợp.', ['RoleBinding gắn quyền trong namespace cho user, group hoặc ServiceAccount.','ClusterRoleBinding áp dụng quyền ở cấp cluster.','Kiểm tra bằng auth can-i để xác minh quyền thực tế.'], 'kubectl create role pod-reader --verb=get,list,watch --resource=pods -n cka-lab\nkubectl create serviceaccount learner -n cka-lab\nkubectl create rolebinding learner-read --role=pod-reader --serviceaccount=cka-lab:learner -n cka-lab\nkubectl auth can-i list pods --as=system:serviceaccount:cka-lab:learner -n cka-lab', 'Cấp quyền chỉ đọc Pod cho learner; xác minh không được xóa Pod. Impersonation cần quyền từ người thực hiện.', 'list pods trả yes và delete pods trả no cho learner.', 'Không cấp cluster-admin chỉ để vượt một lỗi Forbidden chưa phân tích.', '/docs/reference/access-authn-authz/rbac/'],
['ServiceAccount và token','ServiceAccount cung cấp danh tính cho tiến trình chạy trong Pod. Token hiện đại thường được cấp ngắn hạn qua TokenRequest và projected volume.', ['ServiceAccount có namespace.','Gắn serviceAccountName trong Pod spec để dùng danh tính mong muốn.','Tắt automountServiceAccountToken khi workload không cần gọi API.'], 'kubectl get serviceaccounts -n cka-lab\nkubectl explain pod.spec.serviceAccountName\nkubectl explain pod.spec.automountServiceAccountToken', 'Tạo Pod lab dùng learner; kiểm tra Pod spec và đánh giá ứng dụng có cần token API hay không.', 'Đúng ServiceAccount được tham chiếu, quyền chỉ đúng nhu cầu ứng dụng.', 'Token là credential; không in, commit hoặc gửi vào log.', '/docs/concepts/security/service-accounts/'],
['SecurityContext và Pod Security','SecurityContext đặt danh tính và quyền thực thi của tiến trình trong container hoặc Pod. Pod Security Admission có thể áp dụng các mức chính sách cho namespace.', ['runAsNonRoot giúp ngăn chạy bằng UID 0 với image tương thích.','allowPrivilegeEscalation: false và drop capabilities giảm đặc quyền.','readOnlyRootFilesystem cần ứng dụng có nơi ghi phù hợp qua volume.'], 'kubectl explain pod.spec.securityContext\nkubectl explain pod.spec.containers.securityContext\nkubectl get namespace cka-lab --show-labels', 'Viết manifest workload không chạy root với image hỗ trợ; kiểm tra các thư mục cần ghi trước khi bật root filesystem chỉ đọc.', 'Container chạy được với đặc quyền tối thiểu và không bị lỗi quyền ghi ngoài dự kiến.', 'Không bật privileged chỉ để tránh tìm nguyên nhân permission denied.', '/docs/tasks/configure-pod-container/security-context/'],
['NetworkPolicy và ranh giới truy cập','NetworkPolicy mô tả traffic Pod được phép theo ingress/egress, selectors, namespace và IP. Cần network plugin hỗ trợ thực thi chính sách.', ['Mặc định Pod không bị cô lập khi chưa có policy chọn nó cho hướng đó.','Các policy phù hợp được kết hợp theo phép hợp.','Khi cô lập egress, nhớ đường đi DNS và các dịch vụ cần thiết.'], 'kubectl get networkpolicies -A\nkubectl explain networkpolicy.spec\nkubectl get pods -n cka-lab --show-labels', 'Trong lab có CNI hỗ trợ, viết default-deny ingress rồi chỉ cho Pod client có label phù hợp truy cập app.', 'Thử được cả kết nối được phép và kết nối bị chặn.', 'Tạo được đối tượng NetworkPolicy không chứng minh CNI đã thực thi nó.', '/docs/concepts/services-networking/network-policies/']
]},
{title:'Lưu trữ dữ liệu',en:'Storage',intro:'Đưa dữ liệu ra khỏi vòng đời container. Phân biệt volume tạm, PersistentVolume, PersistentVolumeClaim và StorageClass để hiểu cách ứng dụng yêu cầu dung lượng.',goals:['Chọn đúng loại volume.','Đọc quá trình PVC bind với PV.','Phân tích lỗi Pending và mount volume.'],lessons:[
['Volumes và emptyDir','Volume cung cấp vùng lưu trữ được mount vào container. emptyDir sống theo Pod, có thể chia sẻ giữa container trong Pod nhưng mất khi Pod bị loại khỏi node.', ['Container restart không nhất thiết làm mất emptyDir của Pod còn tồn tại.','Pod mới là một vòng đời mới, không giữ emptyDir cũ.','hostPath phụ thuộc filesystem node và cần cân nhắc bảo mật.'], 'kubectl explain pod.spec.volumes.emptyDir\nkubectl explain pod.spec.containers.volumeMounts\nkubectl describe pod <pod> -n cka-lab', 'Dùng hai container chia sẻ emptyDir: một container ghi file, container còn lại đọc file.', 'Cả hai volumeMount trỏ đúng volume name và đọc được cùng dữ liệu.', 'Không dùng emptyDir để lưu dữ liệu cần bền vững qua việc thay Pod.', '/docs/concepts/storage/volumes/'],
['PersistentVolume và PersistentVolumeClaim','PV đại diện tài nguyên lưu trữ của cluster; PVC là yêu cầu của ứng dụng. Pod tham chiếu PVC, còn binding lựa chọn PV đáp ứng dung lượng, access mode và StorageClass.', ['PV là tài nguyên cấp cluster; PVC nằm trong namespace.','Access mode diễn tả khả năng mount; ReadWriteOnce thường là một node, không phải một Pod.','Reclaim policy quyết định xử lý volume sau khi PVC được giải phóng.'], 'kubectl get pv\nkubectl get pvc -n cka-lab\nkubectl describe pvc <claim> -n cka-lab\nkubectl explain persistentvolume.spec.persistentVolumeReclaimPolicy', 'Đọc một PVC/PV trong lab; xác định StorageClass, dung lượng và reclaim policy trước khi thay đổi.', 'Giải thích được Bound/Pending và mối liên hệ PVC–PV.', 'Xóa PVC có thể dẫn tới xóa storage bên dưới nếu policy là Delete.', '/docs/concepts/storage/persistent-volumes/'],
['StorageClass và cấp phát động','StorageClass mô tả cách provisioner tạo storage. PVC có thể kích hoạt cấp phát động; WaitForFirstConsumer trì hoãn binding để cân nhắc topology của workload.', ['Provisioner/CSI driver phụ thuộc môi trường cluster.','StorageClass mặc định có thể áp dụng khi PVC không chỉ định class.','allowVolumeExpansion và hỗ trợ driver quyết định khả năng mở rộng.'], 'kubectl get storageclasses\nkubectl describe storageclass <class>\nkubectl explain persistentvolumeclaim.spec.storageClassName', 'Chọn StorageClass lab đang có, tạo PVC nhỏ và Pod sử dụng; theo dõi Events để hiểu thời điểm provisioning.', 'PVC Bound và Pod mount thành công, hoặc xác định thiếu provisioner/quota/topology.', 'PVC Pending với WaitForFirstConsumer có thể là hành vi bình thường khi chưa có Pod dùng.', '/docs/concepts/storage/storage-classes/'],
['Chẩn đoán lỗi volume','Lỗi lưu trữ có thể xuất hiện ở binding, attach, mount hoặc quyền filesystem. Đọc Events ở cả PVC và Pod để xác định bước đang thất bại.', ['Pending: kiểm tra class, dung lượng, access modes và topology.','FailedAttachVolume: xem hạn chế attach và trạng thái node/driver.','Permission denied trong app: xem UID/GID, fsGroup và quyền thư mục.'], 'kubectl describe pvc <claim> -n cka-lab\nkubectl describe pod <pod> -n cka-lab\nkubectl get events -n cka-lab --sort-by=.metadata.creationTimestamp\nkubectl get csidrivers', 'Dựng một PVC yêu cầu StorageClass không tồn tại trong lab rồi chẩn đoán từ Events; xóa tài nguyên thử khi xong.', 'Chỉ ra chính xác giai đoạn lỗi thay vì xóa PVC rồi tạo lại theo phỏng đoán.', 'Kiểm tra dữ liệu và reclaim policy trước bất kỳ thao tác xóa volume nào.', '/docs/tasks/debug/debug-application/debug-pods/']
]},
{title:'Mạng trong Kubernetes',en:'Networking',intro:'Lần theo một request từ Pod tới Service, DNS và cổng vào cluster. Hiểu mô hình mạng giúp bạn khoanh vùng lỗi nhanh hơn việc thử đổi cấu hình ngẫu nhiên.',goals:['Đọc đường đi Pod network và Service.','Kiểm tra DNS cùng EndpointSlice.','Phân biệt Ingress, Gateway và controller.'],lessons:[
['Pod networking và CNI','Kubernetes yêu cầu mô hình mạng cho các Pod; network plugin thiết lập kết nối theo môi trường. CNI là giao diện cấu hình mạng mà nhiều runtime/plugin sử dụng.', ['Mỗi Pod thường có IP riêng trong Pod network.','Container cùng Pod dùng chung network namespace.','Network plugin có thể dùng overlay, routing hoặc giải pháp khác.'], 'kubectl get pods -A -o wide\nkubectl get nodes -o wide\nkubectl get daemonsets -n kube-system', 'Nhận diện network plugin trong cluster lab và ghi sơ đồ hai Pod ở hai node liên lạc ra sao.', 'Phân biệt Pod CIDR, Service CIDR và địa chỉ node.', 'Không đổi CNI configuration khi chưa hiểu mạng và quy trình phục hồi cluster.', '/docs/concepts/cluster-administration/networking/'],
['Service, kube-proxy và EndpointSlice','Service ánh xạ địa chỉ truy cập ổn định tới các endpoint. kube-proxy hoặc cơ chế dataplane thay thế triển khai phần chuyển tiếp traffic tùy cluster.', ['Service selector tìm Pod theo labels.','EndpointSlice ghi các backend và trạng thái sẵn sàng.','port, targetPort và nodePort là ba khái niệm khác nhau.'], 'kubectl get svc app -n cka-lab -o yaml\nkubectl get endpointslices -n cka-lab -l kubernetes.io/service-name=app\nkubectl get pods -n cka-lab -l app=app --show-labels', 'So sánh selector Service app với label Pod; lần theo targetPort tới cổng ứng dụng.', 'Địa chỉ endpoint khớp Pod Ready và cổng đích đúng.', 'Không sửa Service trước khi kiểm tra ứng dụng có thật sự lắng nghe trên targetPort.', '/docs/concepts/services-networking/service/'],
['CoreDNS và phân giải tên dịch vụ','DNS trong cluster giúp Pod tìm Service bằng tên. Tên đầy đủ thường có dạng service.namespace.svc theo cluster domain đã cấu hình, thường là cluster.local.', ['Tên ngắn phụ thuộc namespace và search domains.','CoreDNS thường chạy trong namespace kube-system.','Kiểm tra resolv.conf và DNS Service trước khi kết luận mạng Pod lỗi.'], 'kubectl run dns-check --image=busybox:1.37 --restart=Never -n cka-lab --command -- sleep 3600\nkubectl exec dns-check -n cka-lab -- nslookup app.cka-lab.svc.cluster.local\nkubectl exec dns-check -n cka-lab -- cat /etc/resolv.conf\nkubectl get pods -n kube-system -l k8s-app=kube-dns', 'Phân giải Service app từ Pod dns-check; điều chỉnh domain nếu cluster dùng domain riêng.', 'DNS trả địa chỉ Service đúng; phân biệt lỗi DNS với lỗi HTTP sau phân giải.', 'NetworkPolicy egress chặn DNS có thể làm mọi tên dịch vụ trông như bị hỏng.', '/docs/tasks/administer-cluster/dns-debugging-resolution/'],
['Ingress và Gateway API','Ingress khai báo định tuyến HTTP(S) nhưng cần Ingress controller thực thi. Gateway API cung cấp tài nguyên như GatewayClass, Gateway, HTTPRoute với mô hình phân chia vai trò rõ hơn.', ['Tạo Ingress đơn thuần không cài controller.','IngressClass/GatewayClass xác định cơ chế thực thi.','Backend Service phải hoạt động trước khi chẩn đoán lớp ingress.'], 'kubectl get ingressclasses\nkubectl get ingress -A\nkubectl api-resources --api-group=gateway.networking.k8s.io\nkubectl get services -n cka-lab', 'Kiểm kê cluster có Ingress controller hoặc Gateway implementation hay chưa; đọc một route nếu có.', 'Nêu được chuỗi client → controller/gateway → Service → Pod.', 'Gateway API cần CRD và implementation phù hợp; không mặc định có trong mọi cluster.', '/docs/concepts/services-networking/gateway/'],
['Xử lý sự cố kết nối theo từng lớp','Chẩn đoán mạng theo thứ tự giúp tìm đúng điểm đứt: tiến trình ứng dụng, Pod IP, Service endpoint, DNS rồi ingress hoặc đường đi bên ngoài.', ['Xác nhận app lắng nghe đúng địa chỉ/cổng.','Kiểm tra Pod Ready và Service selector.','Đánh giá NetworkPolicy, CNI và firewall khi các tầng trên đã rõ.'], 'kubectl port-forward service/app 8080:80 -n cka-lab\n# Trong terminal khác trên máy local:\ncurl -I http://127.0.0.1:8080\n# Dừng port-forward bằng Ctrl+C sau kiểm tra', 'Kiểm tra Service app qua port-forward, sau đó so sánh với kết nối nội bộ từ Pod kiểm tra.', 'Phân biệt port-forward thành công với chứng minh toàn bộ Service dataplane đã hoạt động.', 'Port-forward là đường kiểm tra riêng, không kiểm chứng đầy đủ DNS, ingress hay CNI giữa các node.', '/docs/tasks/debug/debug-application/debug-service/']
]},
{title:'Cài đặt & mở rộng cluster',en:'Cluster Installation & Extensions',intro:'Kết nối kiến thức kiến trúc với một cluster thật. Chuẩn bị kubeadm, hiểu HA, rồi quản lý ứng dụng đóng gói và tài nguyên mở rộng bằng Helm, Kustomize và CRD.',goals:['Lên kế hoạch cài cluster theo môi trường.','Hiểu control plane HA và join node.','Phân biệt templating, overlays và operator.'],lessons:[
['Thiết kế cluster và kubeadm','Trước khi init cluster, cần kiểm tra hệ điều hành, kernel, runtime, mạng và phiên bản gói theo hướng dẫn chính thức. kubeadm bootstrap control plane nhưng không tự giải quyết mọi hạ tầng.', ['Lên kế hoạch địa chỉ API endpoint, Pod CIDR và Service CIDR.','Chuẩn bị CRI runtime và cgroup driver tương thích.','Cài network addon phù hợp sau khi bootstrap theo tài liệu của addon.'], 'kubectl version --client\n# Trên node lab đã cài kubeadm:\nkubeadm version\nsudo kubeadm config images list', 'Viết checklist cài đặt trước khi chạy init; ghi lựa chọn runtime, CNI và IP ranges không chồng lấn.', 'Có thể giải thích mỗi điều kiện chuẩn bị phục vụ thành phần nào.', 'Không chạy kubeadm init trên node đang thuộc cluster khác.', '/docs/setup/production-environment/tools/kubeadm/create-cluster-kubeadm/'],
['Join node và kiến trúc HA','Worker join cluster qua API endpoint và cơ chế bootstrap. Control plane HA cần endpoint ổn định và kế hoạch etcd, có thể dùng stacked etcd hoặc external etcd.', ['Load balancer cho API không thay thế quorum của etcd.','Bootstrap token có thời hạn và cần bảo vệ.','Xác nhận node Ready và workload hoạt động sau join.'], 'kubectl get nodes -o wide\nkubectl get pods -n kube-system -o wide\n# Trên control-plane lab, không chia sẻ token tạo ra:\nsudo kubeadm token list', 'Vẽ topology HA gồm API load balancer, control plane và etcd; mô tả điều gì xảy ra khi mất một thành viên.', 'Phân biệt availability của API endpoint với quorum lưu trữ.', 'Không paste join token thật vào tài liệu công khai hoặc commit Git.', '/docs/setup/production-environment/tools/kubeadm/ha-topology/'],
['Helm: chart, release và values','Helm đóng gói manifest thành chart và quản lý các bản cài đặt gọi là release. Values đưa cấu hình vào template; cần xem manifest render trước khi cài chart chưa quen.', ['Chart là gói; release là một lần cài chart vào cluster.','values mặc định có thể được ghi đè bằng file riêng.','helm template render cục bộ để kiểm tra đầu ra.'], 'helm version\nhelm list -A\n# Với chart cục bộ do bạn chuẩn bị:\nhelm template demo ./chart -f values.yaml\nhelm lint ./chart', 'Đọc chart cục bộ, render và kiểm tra namespace, image, tài nguyên và quyền trước khi cài vào lab.', 'Giải thích được values nào sinh ra trường nào trong manifest.', 'Chart bên ngoài có thể tạo quyền hoặc tài nguyên cluster-wide; luôn đọc đầu ra.', 'https://helm.sh/docs/'],
['Kustomize: base và overlay','Kustomize tùy biến YAML khai báo bằng base, overlay và patches mà không cần template theo chuỗi. kubectl tích hợp việc build/apply kustomization.', ['Base chứa tài nguyên chung.','Overlay thêm khác biệt cho từng môi trường.','Xem đầu ra bằng kubectl kustomize trước khi apply -k.'], '# Với thư mục overlay đã chuẩn bị:\nkubectl kustomize overlays/dev\nkubectl apply --dry-run=client -k overlays/dev\n# Áp dụng vào lab sau khi đọc đầu ra:\nkubectl apply -k overlays/dev', 'Tạo base Deployment và overlay dev thay replicas thành 1, thêm label environment=dev.', 'Manifest đã render giữ cấu trúc hợp lệ và có đúng các thay đổi mong đợi.', 'Chú ý selector khi thay labels; một số trường đã tồn tại không thể đổi trực tiếp.', '/docs/tasks/manage-kubernetes-objects/kustomization/'],
['CRD, custom resource và operator','CRD mở rộng Kubernetes API bằng loại tài nguyên mới. Custom resource là một đối tượng của loại đó; operator thường dùng controller để thực hiện logic vận hành cho các tài nguyên này.', ['CRD định nghĩa schema và phiên bản API mở rộng.','Tạo custom resource không tự sinh hành vi nếu không có controller phù hợp.','Đọc scope, RBAC và conversion trước khi cài phần mở rộng.'], 'kubectl get crds\nkubectl api-resources\nkubectl explain <custom-resource>\n# Chỉ chạy explain khi tài nguyên đã tồn tại trong API', 'Chọn một CRD có sẵn trong cluster lab và tìm controller quản lý nó.', 'Phân biệt định nghĩa API, dữ liệu đối tượng và tiến trình reconcile.', 'Xóa CRD có thể xóa toàn bộ custom resources thuộc loại đó.', '/docs/concepts/extend-kubernetes/api-extension/custom-resources/']
]},
{title:'Xử lý sự cố',en:'Troubleshooting',intro:'Biến quan sát thành quy trình chẩn đoán. Bắt đầu từ phạm vi ảnh hưởng, thu thập bằng chứng rồi chỉ thay đổi những gì giải quyết được giả thuyết cụ thể.',goals:['Chẩn đoán workload và node theo triệu chứng.','Xem log kubelet và runtime khi có quyền.','Xác minh ứng dụng sau khi khắc phục.'],lessons:[
['Pod Pending, ImagePullBackOff và CrashLoopBackOff','Các trạng thái thường gặp đại diện các giai đoạn khác nhau: scheduling, tải image và chạy tiến trình. Dùng Events cùng container state để tránh sửa sai tầng.', ['Pending: kiểm tra tài nguyên, selectors, taints và volume.','ImagePullBackOff: kiểm tra tên/tag image, registry và pull secret.','CrashLoopBackOff: xem logs --previous, exit code, command và probes.'], 'kubectl get pods -n cka-lab -o wide\nkubectl describe pod <pod> -n cka-lab\nkubectl logs <pod> -n cka-lab --previous\nkubectl get pod <pod> -n cka-lab -o yaml', 'Tạo một Pod sai image trong lab và viết báo cáo gồm triệu chứng, bằng chứng, nguyên nhân, sửa chữa, kiểm chứng.', 'Có bằng chứng từ Events hoặc logs hỗ trợ nguyên nhân đã chọn.', 'Không xóa Pod trước khi thu thập log và trạng thái cần thiết.', '/docs/tasks/debug/debug-application/debug-pods/'],
['Node NotReady và kubelet','Node conditions phản ánh sức khỏe node. Khi NotReady, cần kiểm tra kết nối API, kubelet, runtime, network plugin và áp lực tài nguyên.', ['describe node cho conditions và Events.','systemctl và journalctl quan sát dịch vụ kubelet trên node Linux phù hợp.','Kiểm tra disk, memory, certificate và runtime theo bằng chứng.'], 'kubectl describe node <node>\n# Trên node lab Linux dùng systemd:\nsudo systemctl status kubelet\nsudo journalctl -u kubelet --since "15 minutes ago"\nsudo crictl info', 'Đọc trạng thái một node lab, xác định kubelet đang hoạt động và runtime có phản hồi.', 'Gắn kết condition của Node với thông báo cụ thể trong log hoặc trạng thái dịch vụ.', 'Restart kubelet không thay cho chẩn đoán và có thể làm mất dấu diễn biến.', '/docs/tasks/debug/debug-cluster/'],
['Lỗi control plane và chứng chỉ','Khi kubectl không kết nối được, sự cố có thể ở kubeconfig, DNS/endpoint, TLS, API server hoặc etcd. Phân biệt lỗi transport với lỗi xác thực/phân quyền trước.', ['Connection refused khác Unauthorized và Forbidden.','Với kubeadm, control plane thường chạy dạng static Pods.','Quan sát runtime và manifest cục bộ khi API server không sẵn sàng.'], 'kubectl cluster-info\n# Trên control-plane lab:\nsudo crictl ps -a\nsudo journalctl -u kubelet --since "15 minutes ago"\nsudo kubeadm certs check-expiration', 'Lập cây chẩn đoán cho kết nối API thất bại; đánh dấu lệnh nào dùng được khi API không hoạt động.', 'Nêu được nguồn bằng chứng ngoài kubectl khi control plane có vấn đề.', 'Sao lưu cấu hình trước khi sửa static Pod manifest; file phụ trong thư mục manifest cũng có thể gây vấn đề.', '/docs/tasks/debug/debug-cluster/'],
['Ứng dụng không nhận traffic','Một ứng dụng có thể có Pod Running nhưng không nhận được request do readiness, selector, cổng, DNS hoặc policy. Khoanh vùng từ bên trong ra bên ngoài.', ['Kiểm tra app và readiness trước.','Đối chiếu Service selector, EndpointSlice và targetPort.','Kiểm tra DNS, policy rồi controller ingress/gateway.'], 'kubectl get deploy,pods,svc -n cka-lab\nkubectl get endpointslices -n cka-lab\nkubectl describe service app -n cka-lab\nkubectl logs deployment/app -n cka-lab --tail=30', 'Cố ý đổi selector Service trong một bản manifest lab, chẩn đoán endpoint rỗng rồi khôi phục selector đúng.', 'Service có endpoint Ready và client gọi được sau khi sửa.', 'Sửa một lớp mỗi lần để biết thay đổi nào thực sự giải quyết lỗi.', '/docs/tasks/debug/debug-application/debug-service/']
]},
{title:'Thực hành tổng hợp & ôn tập',en:'Practice & Review',intro:'Ghép kiến thức thành các tình huống vận hành hoàn chỉnh. Tự thực hiện trước, dùng tiêu chí kiểm tra để đánh giá, rồi ghi lại phần còn lúng túng.',goals:['Triển khai một ứng dụng có cấu hình và Service.','Thực hành điều tra sự cố có bằng chứng.','Luyện đọc yêu cầu, thao tác và xác minh.'],lessons:[
['Lab: triển khai ứng dụng hoàn chỉnh','Bài tổng hợp nối Deployment, ConfigMap, requests/limits, readiness và Service. Mục tiêu là giải thích được từng quyết định thay vì chỉ tạo ra tài nguyên.', ['Namespace: cka-lab; Deployment: web-lab; replicas: 2.','Image nginx:stable, container port 80; requests CPU 100m/memory 64Mi.','Thêm readiness HTTP / cổng 80 và Service ClusterIP cổng 80.'], 'kubectl create deployment web-lab --image=nginx:stable --replicas=2 -n cka-lab --dry-run=client -o yaml > web-lab.yaml\n# Hoàn thiện manifest theo yêu cầu rồi:\nkubectl apply -f web-lab.yaml\nkubectl expose deployment web-lab --port=80 -n cka-lab\nkubectl rollout status deployment/web-lab -n cka-lab', 'Bổ sung các trường còn thiếu vào YAML; kiểm tra readiness, tài nguyên và EndpointSlice mà không nhìn các bài trước.', '2/2 Pod Ready; template đủ requests; Service có hai endpoint sẵn sàng; HTTP trả kết quả.', 'Không coi kubectl apply thành công là tiêu chí hoàn thành duy nhất.', '/docs/tasks/run-application/run-stateless-application-deployment/'],
['Lab: điều tra và khắc phục sự cố','Một báo cáo sự cố tốt giải thích triệu chứng, phạm vi ảnh hưởng, bằng chứng và cách xác minh sau sửa. Hãy luyện trong namespace lab và tạo từng lỗi riêng biệt.', ['Tình huống 1: image tag không tồn tại.','Tình huống 2: selector Service không khớp.','Tình huống 3: readiness trỏ sai đường dẫn.'], 'kubectl get pods,svc -n cka-lab\nkubectl describe deployment web-lab -n cka-lab\nkubectl get events -n cka-lab --sort-by=.metadata.creationTimestamp\nkubectl rollout status deployment/web-lab -n cka-lab', 'Tạo lần lượt ba lỗi trên, ghi bằng chứng trước khi sửa rồi khôi phục trạng thái tốt sau mỗi lỗi.', 'Mỗi tình huống có nguyên nhân riêng và bài kiểm tra chứng minh đã hết lỗi.', 'Không tạo nhiều lỗi cùng lúc khi mới học vì khó xác định quan hệ nguyên nhân.', '/docs/tasks/debug/'],
['Kỹ năng thao tác và kiểm chứng','Trong bài thực hành có thời gian, cần hiểu yêu cầu, chọn context/namespace, thao tác tối thiểu và dành thời gian xác minh kết quả. Tốc độ đến từ quy trình ổn định.', ['Đọc kỹ tên tài nguyên, namespace và kết quả được yêu cầu.','Dùng explain, --help và dry-run để giảm lỗi cú pháp.','Sau khi sửa, đọc lại tài nguyên thực tế và thử hành vi ứng dụng.'], 'kubectl config current-context\nkubectl explain deployment.spec.strategy\nkubectl get deployment web-lab -n cka-lab -o yaml\nkubectl get pods -n cka-lab -l app=web-lab', 'Đặt một khoảng thời gian tự luyện, triển khai lại web-lab từ yêu cầu rồi tự chấm theo tiêu chí thay vì theo số lệnh đã chạy.', 'Hoàn thành đúng đích, đúng phạm vi và có bằng chứng kiểm tra.', 'Sổ tay không công bố thời lượng, luật hay cấu trúc kỳ thi; xem nguồn chứng nhận chính thức trước khi thi.', '/docs/reference/kubectl/quick-reference/'],
['Tổng kết và kế hoạch học tiếp','Bạn đã đi qua các chủ đề nền tảng để quản trị Kubernetes: kiến trúc, workload, scheduling, cấu hình, mạng, lưu trữ, bảo mật và xử lý sự cố. Bước tiếp theo là làm lại các tình huống với ít trợ giúp hơn.', ['Chọn ba chủ đề yếu nhất từ nhật ký học tập.','Làm lại lab và ghi rõ nguyên nhân mỗi lỗi gặp phải.','Đối chiếu tài liệu đúng phiên bản cluster trước khi áp dụng vào môi trường thật.'], 'kubectl get all -n cka-lab\nkubectl get configmap,secret,pvc,networkpolicy -n cka-lab\n# Đọc danh sách tài nguyên trước khi dọn dẹp.\n# Chỉ xóa namespace lab khi đã chắc chắn không còn dữ liệu cần giữ.', 'Tạo checklist cá nhân: biết giải thích cơ chế, tự thực hiện, tự kiểm tra và tự khắc phục cho từng chủ đề.', 'Có thể dựng ứng dụng và chẩn đoán ít nhất một lỗi ở mỗi lớp mà không cần chép toàn bộ lệnh.', 'Xóa namespace là thao tác xóa nhiều tài nguyên; xem xét dữ liệu và storage trước khi dọn lab.', '/docs/']
]}
];
let lessonId=0; CHAPTERS.forEach((c,i)=>{c.id=i+1;c.lessons=c.lessons.map(r=>({id:++lessonId,chapter:c.id,title:r[0],text:r[1],points:r[2],code:r[3],exercise:r[4],verify:r[5],warning:r[6],source:r[7].startsWith('https:')?r[7]:'https://kubernetes.io'+r[7]}));});
const LESSONS=CHAPTERS.flatMap(c=>c.lessons);
